syntax:
template<typename T1, typename T2> bool is_convertible_pointer(const T1* ptr) {
    // Conversion is allowed if T1 can be converted to T2 with more cv-qualifiers
}

code_example:
#include <iostream>
template<typename T1, typename T2>
void test_conversion(T1* ptr1) {
    T2* ptr2 = ptr1; // Implicit conversion if allowed
    (void)ptr2; // suppress unused variable warning
}
int main() {
    int a = 10;
    const int* pConst = &a;
    int* p = nullptr;
    // Allowed: converting 'int*' to 'const int*'
    p = &a;
    pConst = p; // OK: pointer to non-const to pointer to const
    // Not allowed: converting 'const int*' to 'int*'
    // p = pConst; // Error: cannot convert 'const int*' to 'int*'
    return 0;
}
